FROM (
SELECT `daily_assignment`.*, `staff`.`name`, `staff`.`surname`, `staff`.`employee_id`, `classes`.`class`, `sections`.`section`, `students`.`firstname`, `students`.`middlename`, `students`.`lastname`, `students`.`id` as `student_id`, `students`.`admission_no` as `student_admission_no`, `subjects`.`name` as `subject_name`, `programs`.`title` as `program_title`, count(students.id) as total_student
FROM `daily_assignment`
JOIN `student_session` ON `student_session`.`id` = `daily_assignment`.`student_session_id`
JOIN `classes` ON `classes`.`id` = `student_session`.`class_id`
JOIN `sections` ON `sections`.`id` = `student_session`.`section_id`
JOIN `class_sections` ON `class_sections`.`class_id` = `student_session`.`class_id` AND `class_sections`.`section_id` = `student_session`.`section_id`
JOIN `programs` ON `programs`.`id` = `class_sections`.`program_id`
JOIN `students` ON `students`.`id` = `student_session`.`student_id`
JOIN `subject_group_subjects` ON `subject_group_subjects`.`id` = `daily_assignment`.`subject_group_subject_id`
JOIN `subjects` ON `subjects`.`id` = `subject_group_subjects`.`subject_id`
LEFT JOIN `staff` ON `staff`.`id` = `daily_assignment`.`evaluated_by`
WHERE `student_session`.`class_id` = '28'
AND `student_session`.`section_id` = '5'
AND `class_sections`.`program_id` = '4'
AND `subject_group_subjects`.`subject_group_id` = '5'
AND `subject_group_subjects`.`id` = '9'
AND  date_format(daily_assignment.date,'%Y-%m-%d') between '2025-07-02' and '2025-07-02'
GROUP BY `students`.`id`
) CI_count_all_results
