FROM `daily_assignment`
JOIN `student_session` ON `student_session`.`id` = `daily_assignment`.`student_session_id`
JOIN `classes` ON `classes`.`id` = `student_session`.`class_id`
JOIN `sections` ON `sections`.`id` = `student_session`.`section_id`
JOIN `class_sections` ON `class_sections`.`class_id` = `student_session`.`class_id` AND `class_sections`.`section_id` = `student_session`.`section_id`
JOIN `programs` ON `programs`.`id` = `class_sections`.`program_id`
